import{_ as a,c as o,o as c,af as d}from"./chunks/framework.r60quYNK.js";const p=JSON.parse('{"title":"大理白族自治州 - 2025","description":"","frontmatter":{},"headers":[],"relativePath":"2_articles/travel_record/DaLi.md","filePath":"2_articles/travel_record/DaLi.md"}'),r={name:"2_articles/travel_record/DaLi.md"};function t(i,e,l,n,_,h){return c(),o("div",null,e[0]||(e[0]=[d('<h1 id="大理白族自治州-2025" tabindex="-1">大理白族自治州 - 2025 <a class="header-anchor" href="#大理白族自治州-2025" aria-label="Permalink to &quot;大理白族自治州 - 2025&quot;">​</a></h1><h2 id="_6月10日-6月12日-☀️" tabindex="-1">6月10日 - 6月12日 ☀️ <a class="header-anchor" href="#_6月10日-6月12日-☀️" aria-label="Permalink to &quot;6月10日 - 6月12日 ☀️&quot;">​</a></h2><blockquote><p>我和黛黛同学本科毕业旅行的第二站！</p></blockquote><h3 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h3><p>本科期间，因为异地恋，所以在每年的国庆和五一，我们都会找一个城市见面旅行，但每次去的都是类似于现代化都市的大城市，消费又高，又没有什么好玩的，基本都是网红打卡点式的旅游，所以我们这次把第二站设在了具有<code>苍山洱海</code>的<code>云南大理</code>，畅游祖国大好河山！</p><h3 id="_6月10日" tabindex="-1">6月10日 <a class="header-anchor" href="#_6月10日" aria-label="Permalink to &quot;6月10日&quot;">​</a></h3><p>一大早的五点钟，我们从南昌的酒店出发赶往南昌西站，也是我们第一次一起这么早赶高铁哈哈哈，到了高铁站坐上七点的高铁，俩人在前一天晚上买了一堆零食：瓜子、饮料、面包、泡面等等等等，十个小时的高铁车程，俩人的嘴就没停过，我们一起说说笑笑，一起看电视吃瓜子，一起聊八卦，一起选在南昌拍的照片发朋友圈，黛某人更是表演一人睡三座的霸道行为。晚上七点，我们到达了<code>yong南</code>，八点左右到了订好的民宿，民宿的老板是真的好，我们也是第一次住那么有生活气息的客栈，每天都能撸猫撸狗。放好行李，我们惊叹大理晚上八点多竟然还能太阳暴晒，出去在大理古镇的门口吃了一碗<code>感觉非常不正宗的云南米线</code>和<code>饵丝</code>，恕我直言，确实难吃......吃完我们又去古镇街上散步，用我非常时尚且毒辣的眼光为黛黛选了本次大理最佳出片神器<code>独一无二的披肩和草帽</code>,被她一顿乱夸😎，之后我们又买了墨镜和云南的特色小吃<code>舂鸡脚</code>，然后回酒店为各种摄影设备充电，准备第二天的行程~</p><h3 id="_6月11日" tabindex="-1">6月11日 <a class="header-anchor" href="#_6月11日" aria-label="Permalink to &quot;6月11日&quot;">​</a></h3><p>11号我们起了个大早，八点从酒店收拾好出发前往<code>大理古镇</code>，应该是三个古镇中最大的一个了，在古镇里尝了<code>鲜花饼</code>，给家里人也寄了手工做的鲜花饼(此行为一度被我俩认为我们长大了，知道出门旅游给家里带特产了😋)，在古镇里走了两个小时，无意间找到了古镇网红<code>卖耳环的大爷</code>，大爷给黛黛量身推荐了一对非常无敌巨合适她的耳环，也是本次的出片神器，我也在大爷的小摊上买到了我非常喜欢的手串。之后我们又打车去了<code>崇圣寺三塔</code>，在里面买了我们之后旅行要用的<code>盖章本</code>，体验了<code>白族扎染</code>，看了很久的乌龟，总体下来这种景点好像不是很适合我们两个。中午回去吃了<code>野生菌火锅</code>，汤确实很鲜很好喝，但有些菌子本人还是吃不惯，吃完后租了一辆电动车，开始我们的环洱海之旅。一路骑车到达<code>龙龛码头</code>，非常难受的是洱海的生态道不让外来电动车进去，想骑车必须得租他们一小时好几十的电车，于是我们怒走几公里步行环洱海，在这个码头的生态步道上，我们走走拍拍说说笑笑，找一个机位就猛猛拍半天，拍了很多大理的人生照片，一堆美照，一度被夸大摄影师😎，洱海是真的美！晚上回到古镇，我们本来想感受下大理的烧烤啤酒氛围，结果原先看上的那家街上没有位置而且品种有点少，就去随便找了家烧烤店，黛某人馋主食了，很想吃一口山西特色<code>生炒面</code>，当然大理是没有的，最后成了<code>烧烤+啤酒+扬州炒饭</code>。</p><h3 id="_6月12日" tabindex="-1">6月12日 <a class="header-anchor" href="#_6月12日" aria-label="Permalink to &quot;6月12日&quot;">​</a></h3><p>在大理的第三天，我们一大早租了电动车，先去了小红书上的网红路打卡点，但由于天气不好没拍到好看的照片，之后去了喜洲古镇，一路上20多公里，我们这里看看，那里瞧瞧，完全被大理的景色吸引，一路高歌并被太阳晒着(黛某人的腿都晒下个手印)，在喜洲古镇拍了转角楼打卡点、带小火车的草原，喝了云南特色咖啡(个人感觉有点难喝且非常贵)，从古镇出来后又回到洱海，在洱海边待了最后一个下午：散步、打水漂、捡石头，下午又回到酒店拿了行李，和民宿的猫猫狗狗说了再见，然后打车去大理站，准备前往毕业旅行第三站<code>丽江</code>！</p><p><code>最后更新时间：2025-07-10 21:51:45</code></p>',12)]))}const u=a(r,[["render",t]]);export{p as __pageData,u as default};
